#!/usr/bin/env node
/**
 * Generate src/data/deck-index.generated.ts from the JSON files in agent-files/.
 *
 * The runtime registry (src/data/decks.ts) used to eagerly inline every deck
 * JSON via import.meta.glob({ eager: true }), which produced a single ~580 KB
 * gzipped chunk on first paint. This script extracts metadata only —
 * { id, name, kind, cardCount, subtitle } — into a tiny TypeScript module that
 * the registry can consume synchronously. Card data stays in the JSON files
 * and gets dynamically imported on demand.
 *
 * The generated file is committed (not in .gitignore) so the codebase remains
 * dev-mode-friendly without running this script first. CI / `npm run build`
 * regenerates it via the `prebuild` hook so it's always in sync with the
 * actual JSON contents.
 */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const DECKS_DIR = join(ROOT, "agent-files");
const OUT = join(ROOT, "src/data/deck-index.generated.ts");

function unitFor(kind) {
  if (kind === "vocab") return "words";
  if (kind === "kana") return "characters";
  if (kind === "grammar") return "patterns";
  return "kanji";
}

const files = readdirSync(DECKS_DIR)
  .filter((f) => f.endsWith(".json"))
  .filter((f) => f.startsWith("kana_") || f.startsWith("kanji_") || f.startsWith("vocab_") || f.startsWith("integrated_"))
  .sort();

const entries = [];
for (const file of files) {
  const raw = JSON.parse(readFileSync(join(DECKS_DIR, file), "utf8"));
  if (!raw.deck_id || !raw.deck_name) {
    console.warn(`skip ${file}: missing deck_id or deck_name`);
    continue;
  }
  // Mirror the kind-detection logic in src/data/decks.ts so runtime + index agree.
  const isGrammar =
    file.startsWith("vocab_grammar_") || raw.deck_id.startsWith("grammar-");
  const kind = file.startsWith("kana_")
    ? "kanji" // kana decks render through the kanji code path
    : file.startsWith("vocab_")
      ? isGrammar
        ? "grammar"
        : "vocab"
      : "kanji";
  const cardCount = Array.isArray(raw.cards) ? raw.cards.length : 0;
  const subtitle = raw.subtitle || `${cardCount} ${unitFor(kind)}`;
  // Front-of-card text for every card. Vocab entries store their string under
  // `word`; kanji and kana decks use `kanji`. Used by progress/SRS code paths
  // (Home tile counts, GroupDetail, Stats) that need to iterate keys without
  // pulling the full card payload.
  const cardKeys = Array.isArray(raw.cards)
    ? raw.cards
        .map((c) => (typeof c.word === "string" ? c.word : typeof c.kanji === "string" ? c.kanji : ""))
        .filter(Boolean)
    : [];
  entries.push({
    id: raw.deck_id,
    name: raw.deck_name,
    kind,
    cardCount,
    subtitle,
    file,
    cardKeys,
  });
}

const banner = `/**
 * Auto-generated by scripts/build-deck-index.mjs.
 * DO NOT EDIT BY HAND — re-run \`npm run build:deck-index\` (or \`npm run build\`).
 *
 * Synchronous metadata for every default deck. The runtime registry
 * (src/data/decks.ts) builds Deck shells from this and lazy-loads card data
 * on demand. Keeping this module ~few KB instead of ~600 KB is the whole
 * point — first paint shouldn't pull every JLPT card into memory.
 */
import type { DeckKind } from "@/types";
`;

const indexEntries = entries
  .map(
    (e) =>
      `  { id: ${JSON.stringify(e.id)}, name: ${JSON.stringify(e.name)}, kind: ${JSON.stringify(e.kind)} as DeckKind, cardCount: ${e.cardCount}, subtitle: ${JSON.stringify(e.subtitle)}, file: ${JSON.stringify(e.file)}, cardKeys: ${JSON.stringify(e.cardKeys)} }`,
  )
  .join(",\n");

const out = `${banner}
export interface DeckIndexEntry {
  id: string;
  name: string;
  kind: DeckKind;
  cardCount: number;
  subtitle: string;
  /** JSON filename inside /agent-files (used by the lazy loader). */
  file: string;
  /**
   * Front-of-card string for every card in the deck. Lets progress-keyed
   * lookups (Home tile counts, Stats, MixedReview) iterate without forcing
   * a dynamic import of the full card payload.
   */
  cardKeys: readonly string[];
}

export const DECK_INDEX: readonly DeckIndexEntry[] = [
${indexEntries},
] as const;
`;

writeFileSync(OUT, out);
console.log(
  `✓ deck-index.generated.ts: ${entries.length} decks, ${entries.reduce((a, e) => a + e.cardCount, 0).toLocaleString()} cards total`,
);
